// Parse Settings key-value pairs into a global config object
const items = $input.all();
const config = {
  max_retries: 3,
  retry_delay_minutes: 15,
  poll_interval_minutes: 5,
  missed_window_hours: 24,
  alert_email: 'ops-alerts@agency.internal',
  slack_webhook: '',
  rate_limit_wait_seconds: 2,
};

for (const item of items) {
  const row = item.json;
  if (row.key && row.value !== undefined) {
    const key = String(row.key).trim();
    const val = String(row.value).trim();
    if (['max_retries', 'retry_delay_minutes', 'poll_interval_minutes', 'missed_window_hours', 'rate_limit_wait_seconds'].includes(key)) {
      config[key] = parseInt(val, 10) || config[key];
    } else {
      config[key] = val;
    }
  }
}

return [{ json: { config } }];

// Bulletproof Timezone Converter & Due Filter
let config = { max_retries: 3, retry_delay_minutes: 15, missed_window_hours: 24 };
try { config = $('Parse Settings Config').first().json.config || config; } catch (e) {}

let postItems = [];
try { postItems = $('Sheet - Read Posts').all().map(i => i.json); } catch (e) {
  try { postItems = $input.all().map(i => i.json); } catch (err) { postItems = []; }
}

let brandItems = [];
try { brandItems = $('Sheet - Read Brands').all().map(i => i.json); } catch (e) { brandItems = []; }

let clientItems = [];
try { clientItems = $('Sheet - Read Clients').all().map(i => i.json); } catch (e) { clientItems = []; }

let accountItems = [];
try { accountItems = $('Sheet - Read Social Accounts').all().map(i => i.json); } catch (e) { accountItems = []; }

function parseToUtc(dateStr, timeStr, tz) {
  const [y, m, d] = String(dateStr).split('-').map(Number);
  const [hh, mm] = String(timeStr).split(':').map(Number);
  const testDate = new Date(Date.UTC(y, m - 1, d, hh, mm, 0));
  try {
    const tzFormatter = new Intl.DateTimeFormat('en-US', {
      timeZone: tz || 'UTC',
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hour12: false
    });
    const parts = Object.fromEntries(tzFormatter.formatToParts(testDate).map(p => [p.type, p.value]));
    const tzYear = parseInt(parts.year, 10);
    const tzMonth = parseInt(parts.month, 10);
    const tzDay = parseInt(parts.day, 10);
    let tzHour = parseInt(parts.hour, 10);
    if (tzHour === 24) tzHour = 0;
    const tzMin = parseInt(parts.minute, 10);
    const tzDateInUtc = new Date(Date.UTC(tzYear, tzMonth - 1, tzDay, tzHour, tzMin, 0));
    const offsetMs = tzDateInUtc.getTime() - testDate.getTime();
    return new Date(testDate.getTime() - offsetMs).toISOString();
  } catch (err) {
    return null;
  }
}

const brandMap = new Map();
brandItems.forEach(b => brandMap.set(String(b.brand_id), b));

const clientMap = new Map();
clientItems.forEach(c => clientMap.set(String(c.client_id), c));

const accountMap = new Map();
accountItems.forEach(a => {
  const key = `${a.brand_id}_${String(a.platform).toLowerCase()}`;
  accountMap.set(key, a);
});

const nowUtc = new Date();
const missedWindowHours = config.missed_window_hours || 24;
const missedThresholdUtc = new Date(nowUtc.getTime() - missedWindowHours * 3600 * 1000);
const maxRetries = config.max_retries || 3;
const retryDelayMinutes = config.retry_delay_minutes || 15;

const duePosts = [];
const skippedPosts = [];
const invalidPosts = [];

for (const post of postItems) {
  const status = String(post.status || '').trim();
  const attemptCount = parseInt(post.attempt_count || '0', 10);

  if (status !== 'Scheduled' && status !== 'Retrying') continue;
  if (status === 'Retrying' && attemptCount >= maxRetries) continue;

  if (status === 'Retrying' && post.last_attempt_at) {
    const lastAttempt = new Date(post.last_attempt_at);
    if (!isNaN(lastAttempt.getTime()) && (nowUtc.getTime() - lastAttempt.getTime()) < retryDelayMinutes * 60 * 1000) {
      continue;
    }
  }

  if (post.locked_by_execution && post.updated_at) {
    const lockTime = new Date(post.updated_at);
    if (!isNaN(lockTime.getTime()) && (nowUtc.getTime() - lockTime.getTime()) < 10 * 60 * 1000) {
      continue;
    }
  }

  const brand = brandMap.get(String(post.brand_id)) || {
    brand_id: post.brand_id,
    brand_name: post.brand_name || 'Flower Plant',
    default_timezone: post.timezone || 'Asia/Kolkata',
    status: 'Active'
  };

  const client = clientMap.get(String(brand.client_id || post.client_id)) || {
    client_id: post.client_id || 'CL-001',
    client_name: brand.brand_name || 'Flower Plant',
    status: 'Active'
  };

  let tz = String(post.timezone || '').trim() || (brand && brand.default_timezone ? String(brand.default_timezone).trim() : 'Asia/Kolkata');

  const scheduleDate = String(post.schedule_date || '').trim();
  const scheduleTime = String(post.schedule_time || '').trim();
  if (!scheduleDate || !scheduleTime) {
    invalidPosts.push({
      ...post,
      targetStatus: 'Failed',
      errorCode: 'INVALID_SCHEDULE_FORMAT',
      errorMessage: 'Missing schedule_date or schedule_time in row.',
      scheduled_utc: ''
    });
    continue;
  }

  const scheduledUtcIso = parseToUtc(scheduleDate, scheduleTime, tz);
  if (!scheduledUtcIso) {
    invalidPosts.push({
      ...post,
      targetStatus: 'Failed',
      errorCode: 'INVALID_TIMEZONE',
      errorMessage: `Invalid IANA timezone specifier: "${tz}"`,
      scheduled_utc: ''
    });
    continue;
  }

  const scheduledDateObj = new Date(scheduledUtcIso);

  // Due window: allow up to 10 minute lookahead so current scheduled posts execute cleanly
  if (scheduledDateObj > new Date(nowUtc.getTime() + 10 * 60 * 1000)) {
    continue; // Scheduled for later in the future
  }

  if (scheduledDateObj < missedThresholdUtc) {
    skippedPosts.push({
      ...post,
      targetStatus: 'Skipped',
      errorCode: 'MISSED_WINDOW',
      errorMessage: `Post scheduled for ${scheduledUtcIso} is older than ${missedWindowHours}h cutoff window.`,
      scheduled_utc: scheduledUtcIso
    });
    continue;
  }

  if (String(client.status).toLowerCase() !== 'active') {
    invalidPosts.push({
      ...post,
      targetStatus: 'Failed',
      errorCode: 'CLIENT_PAUSED',
      errorMessage: `Client ID ${post.client_id} is Paused or non-existent.`,
      scheduled_utc: scheduledUtcIso
    });
    continue;
  }

  if (String(brand.status).toLowerCase() !== 'active') {
    invalidPosts.push({
      ...post,
      targetStatus: 'Failed',
      errorCode: 'BRAND_PAUSED',
      errorMessage: `Brand ID ${post.brand_id} (${post.brand_name}) is Paused.`,
      scheduled_utc: scheduledUtcIso
    });
    continue;
  }

  const platform = String(post.platform || '').toLowerCase().trim();
  const accountKey = `${post.brand_id}_${platform}`;
  const fallbackToken = 'EAGVJejn6LZAgBS8mrc3ZB41OBQywsjJS97CZC4yagW3qsd4JPFemxWiKLyjSOryb6L6x2HX7WI9ensmDgFGq0SE4ZBWMV3x29hESjH8nPhWoUZBUQpYdCvOILNTv3cX2zLCxFWLhKpKNFnRNaTpQb6q5gyqXPDgUiUTRtJxPYGQZCWj9VwlPEAUpeZBBQLXMTdhPXrHej4TJJtLcXG2TL35j61K0SyToKqhIoGQ';
  const pageToken = 'EAGVJejn6LZAgBS4H7nAEKZBXV7A50nHZCXft8qMWbTZABEhzR7nYHjfkzCbeTALZCTUs7gmaxCGKR3mZBEJ7rZBSKn1FTP3ZCJvc1gRZCSEZBEAl06Ef7dauZB44gBN3jWYcwzy0IlHJxRhPBqvi1XkiSZCWKW0w4RxNwi92Y0XvtnfIFejuadRA9kZBWTwAUCpEmV5VfYwbOOPuZBEOSDXXTURnt0erbzd4h0Qj7JLOZC8C5L1';

  const account = accountMap.get(accountKey) || {
    brand_id: post.brand_id,
    platform,
    social_media_id: post.social_media_id,
    account_handle: post.brand_name || 'Flower plant',
    connection_status: 'Connected',
    access_token: platform === 'facebook' ? pageToken : fallbackToken
  };

  if (String(account.connection_status).toLowerCase() === 'expired') {
    invalidPosts.push({
      ...post,
      targetStatus: 'Failed',
      errorCode: 'ACCOUNT_EXPIRED',
      errorMessage: `OAuth access token for account ${account.account_handle} on ${platform} is Expired.`,
      scheduled_utc: scheduledUtcIso
    });
    continue;
  }

  duePosts.push({
    ...post,
    scheduled_utc: scheduledUtcIso,
    timezone_resolved: tz,
    account_handle: account.account_handle || post.brand_name,
    social_media_id_resolved: account.social_media_id || post.social_media_id,
    n8n_credential_name: account.n8n_credential_name || 'meta_brand_1_cred',
    access_token: account.access_token || (platform === 'facebook' ? pageToken : fallbackToken),
    client_name: client.client_name,
    contact_email: client.contact_email || ''
  });
}

return [
  {
    json: {
      duePosts,
      skippedPosts,
      invalidPosts,
      dueCount: duePosts.length,
      skippedCount: skippedPosts.length,
      invalidCount: invalidPosts.length,
      executedAt: nowUtc.toISOString()
    }
  }
];

// Unroll due posts for batch processing
const data = $input.first().json;
return data.duePosts.map(post => ({ json: post }));

// Validate content limits and media requirements per platform
const post = $input.first().json;
const platform = String(post.platform || '').toLowerCase().trim();
const caption = String(post.caption || '');
const hashtags = String(post.hashtags || '');
const fullText = (caption + (hashtags ? ' ' + hashtags : '')).trim();
const mediaType = String(post.media_type || 'none').toLowerCase().trim();
const rawMediaUrls = String(post.media_urls || post['media_url(s)'] || '').trim();
const mediaUrls = rawMediaUrls ? rawMediaUrls.split(',').map(u => u.trim()).filter(Boolean) : [];
const postTitle = String(post.post_title || '').trim();

let isValid = true;
let validationError = '';

// Platform-specific character and media rules
if (platform === 'x') {
  if (fullText.length > 280) {
    isValid = false;
    validationError = `X (Twitter) text limit exceeded: ${fullText.length}/280 characters.`;
  }
} else if (platform === 'linkedin') {
  if (fullText.length > 3000) {
    isValid = false;
    validationError = `LinkedIn text limit exceeded: ${fullText.length}/3000 characters.`;
  }
} else if (platform === 'instagram') {
  if (fullText.length > 2200) {
    isValid = false;
    validationError = `Instagram caption limit exceeded: ${fullText.length}/2200 characters.`;
  }
  if (mediaType === 'none' || mediaUrls.length === 0) {
    isValid = false;
    validationError = 'Instagram requires at least one image or video media URL.';
  }
  if (mediaType === 'carousel' && (mediaUrls.length < 2 || mediaUrls.length > 10)) {
    isValid = false;
    validationError = `Instagram carousel requires between 2 and 10 media URLs (provided ${mediaUrls.length}).`;
  }
} else if (platform === 'threads') {
  if (fullText.length > 500) {
    isValid = false;
    validationError = `Threads text limit exceeded: ${fullText.length}/500 characters.`;
  }
} else if (platform === 'facebook') {
  if (fullText.length > 5000) {
    isValid = false;
    validationError = `Facebook post limit exceeded: ${fullText.length}/5000 characters.`;
  }
} else if (platform === 'pinterest') {
  if (fullText.length > 500) {
    isValid = false;
    validationError = `Pinterest description limit exceeded: ${fullText.length}/500 characters.`;
  }
  if (!mediaUrls.length || mediaType !== 'image') {
    isValid = false;
    validationError = 'Pinterest requires a valid image media URL.';
  }
  if (!post.social_media_id_resolved) {
    isValid = false;
    validationError = 'Pinterest requires board_id set in social_media_id.';
  }
} else if (platform === 'youtube') {
  if (!postTitle) {
    isValid = false;
    validationError = 'YouTube requires post_title (video title).';
  } else if (postTitle.length > 100) {
    isValid = false;
    validationError = `YouTube video title exceeds 100 characters: ${postTitle.length}/100.`;
  }
  if (caption.length > 5000) {
    isValid = false;
    validationError = `YouTube description exceeds 5000 characters: ${caption.length}/5000.`;
  }
  if (mediaType !== 'video' || mediaUrls.length === 0) {
    isValid = false;
    validationError = 'YouTube requires media_type "video" with a direct video download URL.';
  }
} else if (platform === 'tiktok') {
  if (mediaType !== 'video' || mediaUrls.length === 0) {
    isValid = false;
    validationError = 'TikTok requires a video media URL.';
  }
}

return [{
  json: {
    ...post,
    fullText,
    mediaUrls,
    mediaType,
    isValid,
    validationError
  }
}];

// Normalize response from all platform HTTP nodes
const post = $('Loop Over Posts (Batch 1)').first().json;
const config = $('Parse Settings Config').first().json.config;
const platform = String(post.platform || '').toLowerCase().trim();
const response = $input.first() ? $input.first().json : {};

const statusCode = response.statusCode || (response.headers ? response.headers.status : 200) || 200;
const body = response.body || response.data || response;
const maxRetries = config.max_retries || 3;
const currentAttempt = parseInt(post.attempt_count || '0', 10) + 1;

let isSuccess = statusCode >= 200 && statusCode < 300;
let platformPostId = '';
let postUrl = '';
let errorCode = '';
let errorMessage = '';

// Check platform-specific error indicators in body
if (body.error || body.errors) {
  isSuccess = false;
  const errObj = body.error || (Array.isArray(body.errors) ? body.errors[0] : body.errors);
  errorMessage = String(errObj.message || errObj.detail || JSON.stringify(errObj)).substring(0, 500);
}

if (isSuccess) {
  if (platform === 'facebook') {
    platformPostId = body.id || body.post_id || '';
    postUrl = `https://facebook.com/${platformPostId}`;
  } else if (platform === 'instagram') {
    platformPostId = body.id || '';
    postUrl = `https://instagram.com/p/${platformPostId}`;
  } else if (platform === 'threads') {
    platformPostId = body.id || '';
    postUrl = `https://threads.net/t/${platformPostId}`;
  } else if (platform === 'linkedin') {
    platformPostId = body.id || (response.headers ? response.headers['x-restli-id'] : '') || '';
    postUrl = platformPostId.includes('urn:li:share:')
      ? `https://www.linkedin.com/feed/update/${platformPostId}`
      : `https://www.linkedin.com/feed/update/urn:li:share:${platformPostId}`;
  } else if (platform === 'x') {
    platformPostId = body.data?.id || body.id || '';
    const handle = (post.account_handle || 'user').replace('@', '');
    postUrl = `https://x.com/${handle}/status/${platformPostId}`;
  } else if (platform === 'youtube') {
    platformPostId = body.id || '';
    postUrl = `https://www.youtube.com/watch?v=${platformPostId}`;
  } else if (platform === 'pinterest') {
    platformPostId = body.id || '';
    postUrl = `https://www.pinterest.com/pin/${platformPostId}`;
  } else if (platform === 'tiktok') {
    platformPostId = body.data?.publish_id || body.publish_id || '';
    const handle = (post.account_handle || 'user').replace('@', '');
    postUrl = `https://www.tiktok.com/@${handle}`;
  }
} else {
  // Error Classification
  const errStr = (errorMessage + ' ' + JSON.stringify(body)).toLowerCase();

  if (statusCode === 401 || statusCode === 403 || errStr.includes('code 190') || errStr.includes('invalid token') || errStr.includes('revoked') || errStr.includes('expired')) {
    errorCode = 'AUTH_ERROR';
    if (!errorMessage) errorMessage = 'Authentication failed: OAuth token expired or unauthorized.';
  } else if (statusCode === 429 || errStr.includes('rate limit') || errStr.includes('quota')) {
    errorCode = 'RATE_LIMIT';
    if (!errorMessage) errorMessage = 'Platform API rate limit reached.';
  } else if (errStr.includes('media') || errStr.includes('aspect ratio') || errStr.includes('resolution') || errStr.includes('duration')) {
    errorCode = 'MEDIA_ERROR';
    if (!errorMessage) errorMessage = 'Media asset failed platform encoding/size requirements.';
  } else if (statusCode >= 500) {
    errorCode = 'PLATFORM_ERROR';
    if (!errorMessage) errorMessage = `Platform internal server error (HTTP ${statusCode}).`;
  } else {
    errorCode = 'UNKNOWN';
    if (!errorMessage) errorMessage = `HTTP ${statusCode}: ${JSON.stringify(body).substring(0, 300)}`;
  }
}

// Determine final post status and retry eligibility
let finalStatus = 'Posted';
if (!isSuccess) {
  const isRetryable = ['RATE_LIMIT', 'PLATFORM_ERROR'].includes(errorCode) || statusCode >= 500 || statusCode === 429;
  if (isRetryable && currentAttempt < maxRetries) {
    finalStatus = 'Retrying';
  } else {
    finalStatus = 'Failed';
  }
}

const nowUtc = new Date().toISOString();

return [{
  json: {
    post_id: post.post_id,
    brand_id: post.brand_id,
    brand_name: post.brand_name,
    client_id: post.client_id,
    client_name: post.client_name,
    platform,
    account_handle: post.account_handle,
    isSuccess,
    finalStatus,
    attempt_count: currentAttempt,
    posted_at: isSuccess ? nowUtc : (post.posted_at || ''),
    platform_post_id: platformPostId,
    post_url: postUrl,
    error_code: isSuccess ? '' : errorCode,
    error_message: isSuccess ? '' : errorMessage.substring(0, 500),
    http_status: statusCode,
    response_summary: isSuccess
      ? `Published on ${platform}. ID: ${platformPostId}`
      : `Error on ${platform} (${errorCode}): ${errorMessage.substring(0, 200)}`,
    timestamp_utc: nowUtc
  }
}];

// Gather skipped and invalid posts from earlier filtering node
const data = $('Timezone Converter & Due Filter').first().json;
const nonDue = [...(data.skippedPosts || []), ...(data.invalidPosts || [])];
return nonDue.map(p => ({ json: p }));

// Generate comprehensive run summary for Email & Slack
const allProcessed = $input.all().map(i => i.json);
const config = $('Parse Settings Config').first().json.config;
const executionId = $execution.id;

let postedCount = 0;
let failedCount = 0;
let retryingCount = 0;
const failureDetails = [];
let hasAuthError = false;

for (const p of allProcessed) {
  if (p.finalStatus === 'Posted') {
    postedCount++;
  } else if (p.finalStatus === 'Retrying') {
    retryingCount++;
    failureDetails.push(`[RETRYING] Post #${p.post_id} (${p.brand_name} - ${p.platform}): ${p.error_code} - ${p.error_message}`);
  } else if (p.finalStatus === 'Failed') {
    failedCount++;
    failureDetails.push(`[FAILED] Post #${p.post_id} (${p.brand_name} - ${p.platform}): ${p.error_code} - ${p.error_message}`);
  }
  if (p.error_code === 'AUTH_ERROR') {
    hasAuthError = true;
  }
}

const summaryText = `*Social Media Automation Execution Summary*
*Execution ID*: ${executionId}
*Timestamp*: ${new Date().toISOString()}
*Total Processed*: ${allProcessed.length}
*Posted Successfully*: ${postedCount}
*Retrying (Transient)*: ${retryingCount}
*Failed (Permanent)*: ${failedCount}
${hasAuthError ? '\n⚠️ *CRITICAL: EXPIRED CREDENTIAL DETECTED! Re-authentication required in Social_Accounts.*' : ''}
${failureDetails.length > 0 ? '\n*Issue Breakdown:*\n' + failureDetails.join('\n') : '\nAll posts published with zero errors.'}`;

return [{
  json: {
    summaryText,
    postedCount,
    failedCount,
    retryingCount,
    hasAuthError,
    alertEmail: config.alert_email,
    slackWebhook: config.slack_webhook
  }
}];
